<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>{{ $attempt->schedule->questionSet->title }}</title><style>body{margin:0;background:#f2f0e8;color:#142b20;font-family:Georgia,serif}header{position:sticky;top:0;background:#173f2c;color:#fff;padding:14px 5%;z-index:3;display:flex;justify-content:space-between}.wrap{max-width:900px;margin:auto;padding:24px}.q{background:#fff;margin:18px 0;padding:22px;border-radius:14px;border-left:5px solid #b68127}.opt{display:block;padding:8px}.saved{font:12px sans-serif;color:#4c6b5a}.actions{display:flex;gap:12px;flex-wrap:wrap}button,a.btn{background:#173f2c;color:#fff;border:0;border-radius:8px;padding:12px 16px;text-decoration:none;font-weight:bold}.danger{background:#9b3d27!important}#guard{display:none;position:fixed;inset:0;background:#10251ff2;color:#fff;z-index:20;place-items:center;padding:25px;text-align:center}#guard.show{display:grid}textarea{width:100%;min-height:110px}</style></head><body><header><b>{{ $attempt->schedule->questionSet->title }}</b><span>{{ $attempt->studentToken->student_name }}</span></header><main class="wrap"><p>{{ $attempt->schedule->questionSet->instructions }}</p><button type="button" onclick="document.documentElement.requestFullscreen?.()">Masuk layar penuh</button><form id="submitForm" method="post" action="{{ route('exam.submit',$attempt->public_id) }}">@csrf @foreach($attempt->schedule->questionSet->questions as $question)<section class="q" data-id="{{ $question->id }}"><b>{{ $loop->iteration }}. {{ $question->prompt }}</b>@if($question->type==='essay')<textarea class="answer">{{ implode('', optional($attempt->answers->firstWhere('question_id',$question->id))->answer ?? []) }}</textarea>@else @foreach(($question->type==='true_false'?['Benar','Salah']:($question->options??[])) as $option)<label class="opt"><input class="answer" type="{{ $question->type==='multiple_response'?'checkbox':'radio' }}" name="q{{ $question->id }}{{ $question->type==='multiple_response'?'[]':'' }}" value="{{ $option }}"> {{ $option }}</label>@endforeach @endif<span class="saved"></span></section>@endforeach<div class="actions"><button>Kirim Jawaban Final</button><a id="emergency" class="btn danger" href="{{ route('exam.emergency',$attempt->public_id) }}">Download Jawaban Darurat Excel</a></div></form></main><div id="guard"><div><h2>Ujian dijeda</h2><p>Anda keluar dari layar ujian. Minta pengawas memasukkan kode untuk melanjutkan.</p><input id="supervisor" type="password" autocomplete="off"><button type="button" onclick="unlock()">Lanjutkan</button><p id="unlockError"></p></div></div><script>
const id=@json($attempt->public_id), csrf=document.querySelector('meta[name=csrf-token]').content, prefix='exam:'+id+':', serverAnswers=@json($attempt->answers->pluck('answer','question_id')); let submitted=false, internalFocus=false;
async function api(path,body){return fetch(`/ujian/${id}/${path}`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify(body)});}
function value(section){const fields=[...section.querySelectorAll('.answer')];if(fields[0]?.type==='radio'||fields[0]?.type==='checkbox')return fields.filter(x=>x.checked).map(x=>x.value);return [fields[0]?.value||''];}
async function save(section){const data={question_id:+section.dataset.id,answer:value(section)};localStorage.setItem(prefix+section.dataset.id,JSON.stringify(data));if(!navigator.onLine)return;try{const r=await api('jawaban',data);if(r.ok){localStorage.removeItem(prefix+section.dataset.id);section.querySelector('.saved').textContent='Tersimpan';}}catch(e){}}
document.querySelectorAll('.q').forEach(s=>{s.querySelectorAll('.answer').forEach(i=>i.addEventListener('change',()=>save(s)));const cached=localStorage.getItem(prefix+s.dataset.id), vals=cached?JSON.parse(cached).answer:(serverAnswers[s.dataset.id]||[]);s.querySelectorAll('.answer').forEach(i=>{if(i.type==='radio'||i.type==='checkbox')i.checked=vals.includes(i.value);else i.value=vals[0]||'';});});
function log(type){const events=JSON.parse(localStorage.getItem(prefix+'events')||'[]');events.push({type,at:new Date().toISOString()});localStorage.setItem(prefix+'events',JSON.stringify(events));if(navigator.onLine)api('event',{type});} function pause(type){log(type);document.getElementById('guard').classList.add('show');}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)pause('fullscreen_exit')});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause('visibility_hidden')});window.addEventListener('blur',()=>{if(!internalFocus)pause('window_blur')});window.addEventListener('offline',()=>log('offline'));window.addEventListener('online',()=>{log('online');document.querySelectorAll('.q').forEach(save)});window.addEventListener('beforeunload',e=>{if(!submitted){log('beforeunload');e.preventDefault();}});document.getElementById('submitForm').addEventListener('submit',async e=>{if(submitted)return;e.preventDefault();if(!navigator.onLine){alert('Tidak ada koneksi. Jawaban tetap tersimpan di perangkat; gunakan Download Jawaban Darurat Excel.');return;}await Promise.all([...document.querySelectorAll('.q')].map(save));submitted=true;e.currentTarget.submit();});
document.getElementById('emergency').addEventListener('click',e=>{if(navigator.onLine)return;e.preventDefault();const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"', rows=[['Nama',@json($attempt->studentToken->student_name)],['NISN',@json($attempt->studentToken->nisn)],['Ujian',@json($attempt->schedule->questionSet->title)],[],['Nomor','Soal','Jawaban']];document.querySelectorAll('.q').forEach((s,i)=>rows.push([i+1,s.querySelector('b').textContent,value(s).join('|')]));rows.push([],['Event','Waktu']);JSON.parse(localStorage.getItem(prefix+'events')||'[]').forEach(x=>rows.push([x.type,x.at]));const content=rows.map(r=>r.map(esc).join(',')).join('\r\n'), hash='offline-'+Date.now(), blob=new Blob(['\ufeff'+content+'\r\n"Hash","'+hash+'"'],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='jawaban-darurat-'+id+'.csv';a.click();URL.revokeObjectURL(a.href);});
async function unlock(){internalFocus=true;const r=await api('unlock',{supervisor_code:document.getElementById('supervisor').value});internalFocus=false;if(r.ok){document.getElementById('guard').classList.remove('show');document.getElementById('supervisor').value='';}else document.getElementById('unlockError').textContent='Kode pengawas salah.';}
</script></body></html>
